head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
scwin.checkVal = function() {
	var ret = true;
	var itemArr1 = scwin.__getObj('G_'+$p.id+'gridView1___selectbox_col1').itemArr;
	var itemArr2 = selectbox1.itemArr;
	if (itemArr1.length !== itemArr2.length) {
		return "length diff";
	}
	for (var i = 0; i < itemArr1.length; i++) {
		if (itemArr1[i].label !== itemArr2[i].label || itemArr1[i].value !== itemArr2[i].value) {
			ret = itemArr1[i].label + "," + itemArr2[i].label + "@@" + itemArr1[i].value + "," + itemArr2[i].value;
			break;
		}
	}
	return ret;
};
scwin.onpageload = function() {
	dataList1.setData(["aa", "11", "bb", "22"]);
	window.arr = [];
	for (var ix = 0; ix < 20; ix++) {
		arr.push("hello" + ix);
	}
	dataList2.setData(arr);
	selectbox1.setNodeSet("data:dataList1", "label", "value");
	if (!tabControl1.isLoaded(1)) {
		var promiseObj = tabControl1.activateTab(1);
		if (promiseObj && typeof promiseObj.then === "function") {
			promiseObj.then(function(s,f){
				gridView1.setColumnNodeSet("col1", "data:dataList1", "label", "value");
			});
		} else {
			gridView1.setColumnNodeSet("col1", "data:dataList1", "label", "value");
		}
	}
	window.dataInputType = WebSquare.util.getDataPrefix("inputtype");
};
